"use client";

/**
 * Terminal session: a terminal window where commands type after a prompt,
 * their output prints in short bursts, a spinner works, and a success line
 * lands in green to close the shot.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/JetBrainsMono";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { Caret, easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: MONO } = loadFont("normal", { weights: ["400", "600"], subsets: ["latin"] });

/** Timing, in frames. */
const START = 14;
const TYPE_RATE = 30;
const AFTER_TYPE = 8;
const PER_OUTPUT = 4;
const SPIN_FRAMES = 30;
/** Success ink. Terminals print success in green whatever the brand colour. */
const GREEN = "oklch(0.7 0.16 150)";
const FONT_SIZE = 34;

export interface TerminalSessionProps {
  /** One entry per line. A line starting with "$ " types after the prompt; any other line prints as output. */
  commands?: string[];
  /** Text in the window's title bar. */
  title?: string;
  /** The green line that lands after the spinner. */
  success?: string;
  /** What the spinner says while it runs. */
  working?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS monospace family the project has loaded. Defaults to the theme's face, then JetBrains Mono. */
  font?: string;
}

interface Line {
  text: string;
  command: boolean;
  /** Frame the line starts to show. */
  at: number;
}

/** Lay every line on the clock: commands type, output prints a line every few frames. */
function schedule(commands: string[], fps: number): { lines: Line[]; spinAt: number } {
  let t = START;
  const lines: Line[] = [];
  for (const raw of commands) {
    const command = raw.startsWith("$ ");
    const text = command ? raw.slice(2) : raw;
    lines.push({ text, command, at: t });
    t += command ? Math.ceil((text.length / TYPE_RATE) * fps) + AFTER_TYPE : PER_OUTPUT;
  }
  return { lines, spinAt: t + 4 };
}

const DEFAULT_COMMANDS = [
  "$ npm install",
  "added 214 packages in 3s",
  "$ npm run build",
  "> compiling 48 modules",
  "> optimizing images",
  "> writing static pages",
];

/** A terminal that types commands, prints output, spins and lands a success line. */
export function TerminalSession({
  commands = DEFAULT_COMMANDS,
  title = "your-project",
  success = "Build complete. Ready to deploy.",
  working = "Bundling",
  theme: themeOverride,
  font,
}: TerminalSessionProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, MONO);
  const { lines, spinAt } = schedule(commands, fps);
  const doneAt = spinAt + SPIN_FRAMES;

  const enter = easings.out(progress(frame, 0, 18));
  const visible = lines.filter((l) => frame >= l.at);
  const typingIndex = visible.length - 1;
  const spinning = frame >= spinAt && frame < doneAt;
  const doneT = easings.out(progress(frame, doneAt, 14));

  const prompt = (
    <span style={{ color: theme.primary, fontWeight: 600 }}>
      ~/{title} <span style={{ color: theme.mutedForeground }}>$</span>{" "}
    </span>
  );

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(ellipse 70% 70% at 50% 40%, ${withAlpha(theme.primary, 0.08)}, ${theme.background} 70%), ${theme.background}`,
        alignItems: "center",
        justifyContent: "center",
        fontFamily: family,
      }}
    >
      <div
        style={{
          width: 1360,
          height: 640,
          borderRadius: theme.radius * 1.5,
          background: theme.card,
          border: `1px solid ${theme.border}`,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          opacity: enter,
          transform: `translateY(${(1 - enter) * 40}px) scale(${0.97 + enter * 0.03})`,
          boxShadow: "0 50px 120px oklch(0 0 0 / 0.18), 0 12px 30px oklch(0 0 0 / 0.08)",
        }}
      >
        <div style={{ height: 64, display: "flex", alignItems: "center", padding: "0 24px", background: theme.muted, borderBottom: `1px solid ${theme.border}`, position: "relative" }}>
          <div style={{ display: "flex", gap: 10 }}>
            {[0, 1, 2].map((i) => (
              <div key={i} style={{ width: 16, height: 16, borderRadius: 8, background: withAlpha(theme.foreground, 0.16) }} />
            ))}
          </div>
          <div style={{ position: "absolute", left: 0, right: 0, textAlign: "center", fontSize: 22, color: theme.mutedForeground }}>{title}</div>
        </div>
        <div style={{ flex: 1, padding: "40px 48px", fontSize: FONT_SIZE, lineHeight: 1.6, color: theme.cardForeground, display: "flex", flexDirection: "column", justifyContent: "flex-end", overflow: "hidden" }}>
          {visible.map((line, i) => {
            if (!line.command) {
              const t = easings.out(progress(frame, line.at, 6));
              return (
                <div key={i} style={{ color: theme.mutedForeground, opacity: t, transform: `translateY(${(1 - t) * 8}px)`, whiteSpace: "pre" }}>
                  {line.text}
                </div>
              );
            }
            const text = line.text.slice(0, Math.max(0, Math.floor(((frame - line.at) / fps) * TYPE_RATE)));
            const typing = text.length < line.text.length;
            const showCaret = i === typingIndex && !spinning && frame < spinAt;
            return (
              <div key={i} style={{ whiteSpace: "pre" }}>
                {prompt}
                {text}
                {showCaret ? <Caret color={theme.foreground} height={FONT_SIZE} solid={typing} /> : null}
              </div>
            );
          })}
          {frame >= spinAt ? (
            <div style={{ display: "flex", gap: 18, color: spinning ? theme.foreground : GREEN, fontWeight: spinning ? 400 : 600 }}>
              {spinning ? (
                <>
                  <svg width={FONT_SIZE} height={FONT_SIZE} viewBox="0 0 20 20" style={{ alignSelf: "center", transform: `rotate(${frame * 14}deg)` }}>
                    <circle cx={10} cy={10} r={7.5} fill="none" stroke={withAlpha(theme.foreground, 0.14)} strokeWidth={2.6} />
                    <path d="M10 2.5 A7.5 7.5 0 0 1 17.5 10" fill="none" stroke={theme.primary} strokeWidth={2.6} strokeLinecap="round" />
                  </svg>
                  <span>
                    {working}
                    {".".repeat(1 + (Math.floor(frame / 8) % 3))}
                  </span>
                </>
              ) : (
                <span style={{ opacity: doneT, transform: `translateX(${(1 - doneT) * -12}px)`, display: "inline-block" }}>✓ {success}</span>
              )}
            </div>
          ) : null}
          {frame >= doneAt ? (
            <div style={{ whiteSpace: "pre", opacity: doneT }}>
              {prompt}
              <Caret color={theme.foreground} height={FONT_SIZE} />
            </div>
          ) : null}
        </div>
      </div>
    </AbsoluteFill>
  );
}
